cat /home/ubuntu/.claude-account-1/projects/-home-ubuntu--agent-ml-research-be-idea-gen-0515-2-projects-importance-margin-vla-compress--claude-sessions-agent-ef2371ad/e0fce467-f72b-48e5-9ef2-d24a1966bb8d/tool-results/mcp-agent-ml-research-read_registry-1779814010281.txt | python3 -c "
import json, sys

data = json.loads(sys.stdin.read())
result = json.loads(data['result'])
exps = result['data']['experiments']

# Build cliff curve data for OpenVLA
# Suites: goal, object, long (libero_10), spatial
# Methods: l2norm, attn (attention), random
# k values of interest: 0.95, 0.9, 0.85, 0.75, 0.7, 0.5

suites = {'goal': 'goal', 'object': 'object', 'long': '10', 'spatial': 'spatial'}
methods = ['l2norm', 'attn', 'random']
k_values = ['k095', 'k09', 'k085', 'k075', 'k07', 'k05']

print('=== OpenVLA Cliff Curve Data ===')
for suite_name in ['goal', 'object', 'long']:
    print(f'\n--- {suite_name.upper()} ---')
    print(f'k     | L2norm          | Attn            | Random')
    print(f'------|-----------------|-----------------|----------------')
    for k in k_values:
        row = f'{k:6s}|'
        for method in methods:
            # Search for matching experiments
            found = None
            running = False
            for exp_id, exp in exps.items():
                if 'openvla' not in exp_id:
                    continue
                if method == 'attn' and ('attn' in exp_id or 'attention' in exp_id):
                    pass
                elif method == 'l2norm' and 'l2norm' in exp_id:
                    pass
                elif method == 'random' and 'random' in exp_id:
                    pass
                else:
                    continue

                if k not in exp_id:
                    continue
                if suite_name not in exp_id and (suite_name == 'long' and ('long' in exp_id or '_10' in exp_id)):
                    pass
                elif suite_name in exp_id:
                    pass
                else:
                    continue

                c = exp.get('conclusion', '')
                s = exp.get('status', '')
                m = exp.get('metrics', {})
                sr = m.get('overall_sr', m.get('success_rate', ''))

                if c == 'success' and sr:
                    if not found or (isinstance(sr, (int, float)) and sr > 0):
                        found = f'{sr}'
                elif c == 'negative' and sr:
                    found = f'{sr}(neg)'
                elif s == 'RUNNING':
                    running = True

            if found:
                row += f' {found:16s}|'
            elif running:
                row += f' 🏃 running       |'
            else:
                row += f' —               |'
        print(row)
" 2>&1 | head -40
